  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  max-height: 2.5rem; /* Fallback for 2 lines of text-sm */
}
.clearfix::after {
  content: "";
  display: table;
  clear: both;
}
